UPDATE ai_quota_ledger
SET status = 'COMMITTED',
    updated_at = UTC_TIMESTAMP(3)
WHERE user_id = #{userId}
  AND request_id = #{requestId}
  AND status = 'RESERVED'

UPDATE ai_quota_ledger
SET status = 'RELEASED',
    updated_at = UTC_TIMESTAMP(3)
WHERE user_id = #{userId}
  AND request_id = #{requestId}
  AND status = 'RESERVED'
